using System;

namespace TouchTypingStudio;

// A reading aid, not the answer key: do not include an executable solution,
// generated incident ID, exact test value or a hint about which key to press.
internal sealed record ConsoleTheory(string Shell, string Title, string Why, string Observe)
{
    internal static ConsoleTheory For(LabTask task, LabScene scene, bool guided)
    {
        var window = scene.Active;
        if (task.Action != "command" || window == null || scene.Overview ||
            !(window.App == "terminal" || window.Focus is "terminal" or "reverse-search")) return null;
        bool ps = scene.Terminal.IsPowerShell;
        ConsoleTheory Card(string title, string why, string observe) =>
            new(ps ? "PowerShell" : "Bash", title, why, observe);
        if (LiveCourse.TerminalIncidentTask(task.Id))
            return Card("Собрать историю одной попытки", guided ?
                (ps ? "Select-String" : "grep") + " ищет по тексту. На этот раз ищем по номеру операции, а не по слову ERROR: так видны и начало, и сбой." :
                "В журнале перемешаны разные операции. У каждой свой номер, как у посылки.",
                "У начала операции и у сообщения о сбое должен быть один номер. Так вы не припишете ей чужую ошибку.");
        string cmd = task.Text.Trim();
        if (scene.PracticalTerminal)
        {
            if (cmd == scene.TerminalFollowCommand)
                return Card("Увидеть сбой в момент появления", guided ?
                    (ps ? "Get-Content читает журнал, а -Wait ждёт продолжения." : "tail показывает конец журнала, а -f ждёт продолжения.") +
                    " Так вы увидите следующую попытку, не открывая файл заново." :
                    "При обычном чтении вы видите только то, что уже записано. А нам нужна следующая попытка.",
                    "Новые строки появятся сами. Пока идёт просмотр, приглашения для ввода нет. Остановка просмотра не выключит службу.");
            if (cmd.StartsWith("grep ERROR ", StringComparison.Ordinal) || cmd.StartsWith("Select-String ERROR ", StringComparison.Ordinal))
                return Card("Отделить ошибки от обычных записей", guided ?
                    (ps ? "Select-String ищет строки в sync.log" : "grep ищет строки в app.log") +
                    ", а ERROR означает «ошибка». Так не придётся читать все сообщения подряд." :
                    "Журнал хранит и сбои, и сообщения об успехе. Сначала посмотрите, что уже случалось.",
                    ps ? "Рядом со строкой ошибки видны файл и номер строки. Это уже записанный сбой, не новая попытка." :
                         "На экране останутся строки с отметкой ошибки. Исходный файл не изменится. Найденный сбой уже был в журнале.");
        }
        // Match only command families present in the curriculum. Unknown lessons
        // get no panel rather than a generic paragraph pretending to explain them.
        string verb = cmd.Split(' ', 2)[0];
        string after = cmd.Contains(' ') ? cmd[(cmd.IndexOf(' ') + 1)..] : "";
        if (verb == "sudo") { verb = after.Split(' ', 2)[0]; after = after.Contains(' ') ? after[(after.IndexOf(' ') + 1)..] : ""; }
        if (verb == "git") return after.Split(' ', 2)[0] switch {
            "init" => Card("Включить историю проекта", "Чтобы потом сравнить версии файлов, сначала нужна папка, в которой Git будет вести историю.", "Появится сообщение о репозитории. Файлы ещё не записаны в историю."),
            "status" => Card("Проверить состав изменений", "Перед сохранением версии важно не захватить случайные файлы.", "Отличите файлы, уже намеченные к записи, от остальных изменений."),
            "diff" => Card("Увидеть саму правку", "Список имён не показывает, правильно ли изменён текст.", "Сравните удалённые и добавленные строки. Эта проверка не меняет файл."),
            "add" => Card("Выбрать правки для версии", "Git сохраняет подготовленные изменения, а не всё, что открыто в редакторе.", "Проверьте выбранные файлы в статусе. Версия ещё не создана."),
            "commit" => Card("Сохранить проверенную версию", "К именованному состоянию проекта можно будет вернуться и понять, что поменялось.", "Найдите новую запись в истории. Она относится к подготовленным изменениям."),
            "log" => Card("Проверить историю версий", "Нужно убедиться, что правка записана, а не просто осталась в рабочей папке.", "Прочитайте последнюю запись: короткий номер версии и её описание."),
            _ => null
        };
        if (verb == "apt") return after.Split(' ', 2)[0] switch {
            "search" => Card("Подобрать программу", "Сначала ищут нужный пакет, чтобы не установить другой с похожим именем.", "Сверьте имя и назначение в списке. Установка ещё не началась."),
            "show" => Card("Уточнить, что за пакет", "Описание помогает отличить нужный инструмент от одноимённого.", "Найдите имя и описание. Просмотр сведений не устанавливает программу."),
            "install" => Card("Добавить недостающий инструмент", "Дальше упражнению нужна программа, которой ещё нет в учебной системе.", "После установки можно вызвать инструмент. Ваш компьютер тренажёр не меняет."),
            "update" => Card("Обновить список пакетов", "Перед установкой полезно получить свежие сведения о доступных версиях.", "Обновится перечень, а не сами программы. Здесь меняется только учебная система."),
            _ => null
        };
        return verb switch {
            "pwd" => Card("Проверить свою папку", "После переключения окон легко продолжить работу не в том проекте.", "Прочитайте полный путь. От него будут отсчитываться короткие имена файлов."),
            "ls" => Card("Сверить содержимое папки", "Здесь нужно проверить имя файла или результат копирования. В обычной работе то же можно сделать в проводнике.",
                after.Contains("-l") ? "Рядом с именами видны сведения о файлах. Проверьте нужную запись." : "В списке должны быть ожидаемые имена. Просмотр ничего не перемещает."),
            "cd" => Card(after.Length == 0 ? "Вернуться в домашнюю папку" : "Перейти к рабочим файлам", "Следующая команда будет искать файлы относительно текущей папки.", "При успехе список файлов не выводится. Новый путь можно сверить в приглашении."),
            "grep" when cmd.Contains('>') => Card("Сохранить выдержку из журнала", "Коллеге нужны строки про сбой, а не весь длинный журнал.", "Совпадения попадут в отдельный файл вместо экрана. Откройте его и проверьте строки."),
            "grep" => Card("Найти строки по признаку", "Когда файл длинный, читать его целиком не нужно: оставьте только записи с нужным текстом.", "Проверьте содержимое найденных строк. Пустой вывод означает, что совпадений не видно."),
            "head" when cmd.Contains('>') => Card("Подготовить короткую сводку", "Для передачи нужны первые строки документа, а не весь оригинал.", "Выдержка записана в отдельный файл. Откройте его и сравните начало с исходником."),
            "head" or "tail" => Card(verb == "head" ? "Проверить начало файла" : "Проверить конец файла", "По нескольким строкам можно сверить содержимое, не открывая весь документ.", "Видна только часть файла. Остальной текст не удалён."),
            "wc" => Card("Проверить объём результата", "Количество строк помогает быстро заметить пустую или неполную выгрузку.", "Сверьте число с ожидаемым объёмом. Само по себе равенство не доказывает, что тексты одинаковы."),
            "cat" => Card("Прочитать сохранённый файл", "После правки или копирования важно проверить сам файл, а не надпись об успехе.", "Сравните выведенный текст с тем, что собирались сохранить или передать."),
            "mkdir" => Card("Подготовить папку назначения", "Для копии или отчёта нужно своё место, чтобы не смешать его с исходниками.", "При успехе вывода обычно нет. Проверьте, что папка появилась под нужным именем."),
            "cp" => Card("Сделать отдельную копию", "Так можно передать результат или сохранить исходник до правки.", "Оригинал останется на месте. Сверьте содержимое по новому пути."),
            "sort" when cmd.Contains("uniq") => Card("Собрать список без повторов", "Одинаковые метки из разных записей не должны считаться несколько раз.", "В файле результата каждая одинаковая строка останется один раз. Исходные заметки сохранятся."),
            "sort" => Card("Сгруппировать одинаковые строки", "Когда одинаковые метки стоят рядом, их проще сравнить и убрать повторы.", "На экране появятся отсортированные строки. Сам файл пока не изменён."),
            "echo" => Card(cmd.Contains(">>") ? "Дополнить файл" : "Записать строку в файл",
                cmd.Contains(">>") ? "Уточнение нужно добавить после старых записей, а не вместо них." : "Короткую запись нужно оставить в проекте, а не только на экране.",
                cmd.Contains(">>") ? "Проверьте последнюю строку: прежний текст должен остаться выше." : "Один знак > заменяет прежнее содержимое файла. Проверьте результат чтением."),
            "id" or "whoami" => Card("Проверить учётную запись", "Это разовая проверка, если не хватает прав или открыт чужой сеанс. Для обычной работы запоминать имя не нужно.",
                verb == "id" ? "Помимо имени видны группы пользователя. От них могут зависеть права." : "На экране имя пользователя этой оболочки, не название папки."),
            "chmod" => Card("Ограничить доступ к файлу", "Если отчёт предназначен только владельцу, другим пользователям не нужны права на него.", "Сверьте права после изменения: владелец читает и пишет, остальные доступа не имеют."),
            "touch" => Card("Подготовить файл для записи", "Пустой файл нужен, чтобы настроить доступ до появления содержимого.", "Появится файл с заданным именем. Если он уже существовал, его текст не стирается."),
            "find" => Card("Найти файл во вложенных папках", "Когда путь неизвестен, не обязательно открывать каждую папку вручную.", "В результатах есть путь к каждому совпадению. Так одноимённые файлы можно различить."),
            "tree" => Card("Разобраться в структуре папок", "Дерево показывает вложенность, которую не видно в плоском списке.", "По отступам проследите путь от проекта до нужного файла."),
            "history" => Card("Вспомнить прошлое действие", "Если длинная команда уже работала, её можно найти и сверить вместо повторного набора.", "Появится список выполненных команд. Просмотр не запускает их повторно."),
            "clear" => Card("Освободить экран", "Старые сообщения мешают увидеть результат следующей проверки.", "Экран очистится; файлы и история команд останутся."),
            "ps" when cmd.Contains('>') => Card("Сохранить список процессов", "Для разбора неполадки нужен снимок того, что работало в этот момент.", "Список попадёт в файл. Это снимок, а не постоянно обновляемый экран."),
            "ps" => Card("Проверить, что запущено", "Список процессов помогает выяснить, работает ли нужная программа.", "Рядом с программой есть номер процесса. Одна проверка ничего не останавливает."),
            "uname" => Card("Уточнить систему для диагностики", "Сведения о системе нужны, например, когда поддержка просит составить отчёт.", "Прочитайте название системы; при подробном запросе появятся и сведения о версии."),
            "reboot" => Card("Проверить состояние после перезапуска", "Здесь перезапускается учебная система. На настоящем компьютере сначала сохраняют работу.", "Проверьте путь после возврата приглашения. Настоящий компьютер не перезагрузится."),
            "python" or "python3" when after.StartsWith("-m unittest ") => Card("Проверить исправление тестом", "Сохранение кода ещё не доказывает, что ошибка исчезла. Тест проверит нужное поведение.", "При успехе появится OK. Если проверка не прошла, посмотрите, какой результат отличался."),
            _ => null
        };
    }
}
